inserted_products as (
  insert into public.products (
    category_id,
    slug,
    name,
    description,
    image_url,
    price_label,
    code,
    featured,
    active,
    sort_order
  )
  select
    c.id,
    v.slug,
    v.name,
    v.description,
    v.image_url,
    v.price_label,
    v.code,
    v.featured,
    v.active,
    coalesce((select max(sort_order) from public.products), 0) + row_number() over (order by v.sort_order)
  from product_source v
  join public.categories c on c.slug = v.category_slug
  on conflict (slug) do update set
    name = excluded.name,
    description = excluded.description,
    code = excluded.code,
    active = excluded.active
  returning id, slug
),
