insert into public.product_categories (product_id, category_id, sort_order)
select p.id, c.id, cl.sort_order
from category_links cl
join public.products p on p.slug = cl.product_slug
join public.categories c on c.slug = cl.category_slug
on conflict (product_id, category_id) do update set
  sort_order = excluded.sort_order;

commit;
